export async function getClaimRoundInstructionAsync<
  TAccountPlayer extends string,
  TAccountSession extends string,
  TAccountRound extends string,
  TAccountPosition extends string,
  TAccountSessionTreasury extends string,
  TAccountSystemProgram extends string,
  TProgramAddress extends Address = typeof SPOTR_MARKETS_PROGRAM_ADDRESS,
>(
  input: ClaimRoundAsyncInput<
    TAccountPlayer,
    TAccountSession,
    TAccountRound,
    TAccountPosition,
    TAccountSessionTreasury,
    TAccountSystemProgram
  >,
  config?: { programAddress?: TProgramAddress },
): Promise<
  ClaimRoundInstruction<
    TProgramAddress,
    TAccountPlayer,
    TAccountSession,
    TAccountRound,
    TAccountPosition,
    TAccountSessionTreasury,
    TAccountSystemProgram
  >
> {
  // Program address.
  const programAddress =
    config?.programAddress ?? SPOTR_MARKETS_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    player: { value: input.player ?? null, isWritable: true },
    session: { value: input.session ?? null, isWritable: false },
    round: { value: input.round ?? null, isWritable: false },
    position: { value: input.position ?? null, isWritable: true },
    sessionTreasury: { value: input.sessionTreasury ?? null, isWritable: true },
    systemProgram: { value: input.systemProgram ?? null, isWritable: false },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedAccount
  >;

  // Resolve default values.
  if (!accounts.position.value) {
    accounts.position.value = await findPositionPda({
      round: expectAddress(accounts.round.value),
      player: expectAddress(accounts.player.value),
    });
  }
  if (!accounts.sessionTreasury.value) {
    accounts.sessionTreasury.value = await findSessionTreasuryPda({
      session: expectAddress(accounts.session.value),
    });
  }
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value =
      "11111111111111111111111111111111" as Address<"11111111111111111111111111111111">;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta(accounts.player),
      getAccountMeta(accounts.session),
      getAccountMeta(accounts.round),
      getAccountMeta(accounts.position),
      getAccountMeta(accounts.sessionTreasury),
      getAccountMeta(accounts.systemProgram),
    ],
    data: getClaimRoundInstructionDataEncoder().encode({}),
    programAddress,
  } as ClaimRoundInstruction<
    TProgramAddress,
    TAccountPlayer,
    TAccountSession,
    TAccountRound,
    TAccountPosition,
    TAccountSessionTreasury,
    TAccountSystemProgram
  >);
}

